import { useIntl } from 'react-intl';

import { BigNumber, ChartHeader, DataStateHandler } from 'components';
import type { BigNumbersKpiData } from 'pages/pillars/PortfolioBrand/BrandPowerBookExport/types';

import { StyledBigNumbers } from './BigNumbers.styles';

type PowerBigNumberData = Partial<BigNumbersKpiData>;

export interface PowerBigNumbers {
  powerVsLq: PowerBigNumberData;
  powerVsLy: PowerBigNumberData;
}

export interface BigNumbersProps {
  loading: boolean;
  error: Error | null;
  powerVsLq: PowerBigNumberData;
  powerVsLy: PowerBigNumberData;
  selectedPeriodType?: string;
  dataTestId?: string;
}
export const BigNumbers = ({
  loading,
  error,
  powerVsLq,
  powerVsLy,
  selectedPeriodType,
  dataTestId,
}: BigNumbersProps) => {
  const { formatMessage } = useIntl();
  const cardWidth = '236px';
  const normalizedSelectedPeriodType = selectedPeriodType?.toUpperCase();
  const isYtd = normalizedSelectedPeriodType
    ? normalizedSelectedPeriodType === 'YTD'
    : powerVsLy?.periodType === 'YTD';
  const cards = [
    {
      key: 'ly',
      data: powerVsLy,
      tooltipId: isYtd
        ? 'PortfolioBrand.BrandPowerBook.PowerBook.BigNumbers.ly.ytd.tooltip'
        : 'PortfolioBrand.BrandPowerBook.PowerBook.BigNumbers.ly.tooltip',
    },
    ...(isYtd
      ? []
      : [
          {
            key: 'lq',
            data: powerVsLq,
            tooltipId:
              'PortfolioBrand.BrandPowerBook.PowerBook.BigNumbers.lq.tooltip',
          },
        ]),
  ];
  const isEmpty = cards.length > 0 && cards.every((card) => card.data?.empty);

  return (
    <StyledBigNumbers data-testid={dataTestId}>
      <DataStateHandler
        loading={loading}
        error={error}
        empty={isEmpty}
        message={{
          description: formatMessage({
            id: 'Common.dataUnavailable.title',
            defaultMessage: 'Data not available',
          }),
        }}
        skeletonProps={{
          length: isYtd ? 1 : 2,
          width: '236px',
          height: '133px',
          borderRadius: 'none',
        }}
      >
        {cards.map((card) => (
          <BigNumber
            key={card.key}
            data={card.data?.data || []}
            header={
              <ChartHeader
                title={card.data?.header?.title || ''}
                info={formatMessage({ id: card.tooltipId })}
                config={{ inline: 'vertical', type: 'small' }}
              />
            }
            asCard
            size="small"
            style={{ width: cardWidth }}
          />
        ))}
      </DataStateHandler>
    </StyledBigNumbers>
  );
};
